mapper.update:
UPDATE session
   SET agent_id = #{newAgentId}, status = #{newStatus}, update_time = CURRENT_TIMESTAMP
 WHERE id = #{sessionId}
   AND tenant_code = #{tenantCode}
   AND agent_id = #{expectedAgentId}
   AND status = 3
   AND is_deleted = FALSE

mapper.select:
SELECT id
  FROM session
 WHERE tenant_code = #{tenantCode}
   AND id = #{sessionId}
   AND is_deleted = FALSE
 FOR UPDATE

SELECT EXTRACT(HOUR FROM s.start_time)::int AS hour,
       COUNT(1)                             AS cnt
  FROM session s
 WHERE s.tenant_code = #{tenantCode}
   AND s.is_deleted = FALSE
   AND s.start_time >= #{dayStart}
   AND s.start_time < #{now}
 GROUP BY 1
 ORDER BY 1

SELECT s.intent AS name, COUNT(1) AS cnt
  FROM session s
 WHERE s.tenant_code = #{tenantCode}
   AND s.is_deleted = FALSE
   AND s.intent IS NOT NULL AND s.intent <> ''
   AND s.start_time >= #{dayStart}
   AND s.start_time < #{now}
 GROUP BY 1
 ORDER BY cnt DESC
 LIMIT 6

SELECT COALESCE(s.emotion, '中性') AS name, COUNT(1) AS cnt
  FROM session s
 WHERE s.tenant_code = #{tenantCode}
   AND s.is_deleted = FALSE
   AND s.start_time >= #{dayStart}
   AND s.start_time < #{now}
 GROUP BY 1
 ORDER BY cnt DESC

SELECT s.session_no AS session_no, s.status AS status, s.source AS source, s.intent AS intent, s.emotion AS emotion, s.csat_score AS csat_score, s.start_time AS start_time, s.end_time AS end_time, c.name AS customer_name, COALESCE(mc.msg_count, 0) AS msg_count FROM session s LEFT JOIN customer c ON c.id = s.customer_id LEFT JOIN LATERAL ( SELECT COUNT(1) AS msg_count FROM session_message m WHERE m.tenant_code = s.tenant_code AND m.session_id = s.id AND m.is_deleted = FALSE ) mc ON TRUE WHERE s.tenant_code = #{tenantCode} AND s.is_deleted = FALSE AND s.start_time >= #{from} AND s.start_time < #{to}
AND s.agent_id = #{agentId}
AND s.agent_id IS NULL
ORDER BY s.start_time DESC, s.id DESC LIMIT #{limit}

SELECT s.customer_id AS customer_id, COUNT(1) AS session_count, MAX(s.create_time) AS last_session_at, COUNT(1) FILTER (WHERE s.agent_id IS NOT NULL) AS human_count, COUNT(1) FILTER (WHERE s.status = 4) AS closed_count, COUNT(1) FILTER (WHERE s.status IN (1, 3)) AS open_count FROM session s WHERE s.tenant_code = #{tenantCode} AND s.is_deleted = FALSE AND s.customer_id IN
#{id}
GROUP BY s.customer_id

SELECT DISTINCT ON (s.customer_id) s.customer_id AS customer_id, s.session_no AS session_no, s.status AS status, s.intent AS intent, s.emotion AS emotion, s.source AS source, s.create_time AS create_time, s.end_time AS end_time FROM session s WHERE s.tenant_code = #{tenantCode} AND s.is_deleted = FALSE AND s.customer_id IN
#{id}
ORDER BY s.customer_id, s.create_time DESC, s.id DESC
